const repo = 'rrrugved/dsai_agent_project';
const branch = 'master';

const workflow = {
  repository: repo,
  branch,
  components: [
    'FastAPI backend (backend/main.py)',
    'Streamlit frontend (frontend/app.py)',
    'Agent service orchestration (backend/service.py)',
    'Combined startup script (start.sh)'
  ],
  runtimePorts: {
    backend: 8000,
    frontend: 10000
  },
  endpoints: [
    'GET /',
    'GET /health',
    'POST /chat',
    'POST /chat/stream'
  ],
  startupFlow: [
    'Start FastAPI with uvicorn backend.main:app --host 0.0.0.0 --port 8000',
    'Start Streamlit frontend on 0.0.0.0:10000',
    'Frontend sends chat requests to backend endpoints'
  ],
  notes: [
    'This n8n workflow mirrors repository architecture and execution flow.',
    'It is designed for inspection/documentation in n8n and can be extended to run shell commands via SSH/Execute Command nodes.'
  ]
};

return [{ json: workflow }];

